// MERCADO , alimenta a amostra do heatmap na home com a analise diaria real.
// So a AMOSTRA: o heatmap de verdade e o widget do TradingView na pagina propria.
// ANALISE + GAMMA do NQ , a previa da home mostrava ES 5,621.50 com texto inventado
// ("Macro tariffs weigh on global markets..."). Analise de mercado inventada e o pior tipo
// de dado falso num site de trading: o cara confere o preco no proprio grafico.
_mcLigarAnalise() {
  if (this._mcAnaBuscou) return;
  this._mcAnaBuscou = true;
  var self = this;
  var AN = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFmd2hkdXZ1dGZ1bXNheG51b2ZhIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzQzNzc5NDYsImV4cCI6MjA4OTk1Mzk0Nn0.efRel6U68misvPSRj8-p31-gOhzjXN4eIFMiloTNyk4';
  var H = { headers: { apikey: AN, Authorization: 'Bearer ' + AN } };
  var SB = 'https://qfwhduvutfumsaxnuofa.supabase.co/rest/v1/';
  Promise.all([
    fetch(SB + 'daily_analysis?asset=eq.NQ&select=*&order=date.desc&limit=1', H).then(function (r) { return r.ok ? r.json() : []; }),
    fetch(SB + 'gex_levels?ticker=eq.NQ&select=*&order=date.desc&limit=1', H).then(function (r) { return r.ok ? r.json() : []; }),
    fetch(SB + 'daily_analysis?asset=eq.ES&select=last_price,change_pct&order=date.desc&limit=1', H).then(function (r) { return r.ok ? r.json() : []; })
  ]).then(function (res) {
    var a = (res[0] || [])[0], g = (res[1] || [])[0];
    // Fita do Live Room: o pacote trazia ES 5,621.50 fixo , 2.100 pontos abaixo do real.
    var e = (res[2] || [])[0];
    if (e) self._mcEs = {
      preco: Number(e.last_price).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }),
      variacao: (e.change_pct > 0 ? '+' : '') + e.change_pct + '%',
      cor: e.change_pct >= 0 ? '#34d399' : '#f87171'
    };
    if (a) {
      // attention_zone e MULTILINGUE no banco (objeto {en,es,pt...}), nao string.
      // Sem tratar, a tela mostraria "[object Object]".
      var z = a.attention_zone;
      var txt = (z && typeof z === 'object') ? (z.en || z.pt || '') : (z || '');
      self._mcAna = {
        titulo: (a.asset || 'NQ') + ' · ' + (a.asset_name || 'Nasdaq 100'),
        preco: Number(a.last_price).toLocaleString('en-US', { maximumFractionDigits: 2 }),
        variacao: ((a.change_pct > 0 ? '+' : '') + a.change_pct + '%'),
        corVar: (a.change_pct >= 0 ? '#34d399' : '#f87171'),
        vies: String(a.bias || '').toUpperCase(),
        texto: String(txt).slice(0, 240),
        s1: a.support_1, s2: a.support_2, r1: a.resistance_1, r2: a.resistance_2
      };
    }
    if (g) self._mcGex = g;
    // CARDS DO GEX , NQ e ES com nivel REAL de gex_levels e barras do top_strikes.
    // A demo trazia niveis inventados (NQ zero gamma 29,027, put 29,000...) e as barras
    // eram `20 + ((i*37) % 70)` , ou seja, largura por FORMULA, sem relacao com gamma
    // nenhum. Grafico de gamma inventado num site que vende leitura de gamma e o pior
    // lugar possivel pra dado falso.
    fetch(SB + 'gex_levels?ticker=in.(NQ,ES)&select=*&order=date.desc&limit=8', H)
      .then(function (r) { return r.ok ? r.json() : []; })
      .then(function (gs) {
        if (!gs || !gs.length) return;
        var vistos = {}, cards = [];
        var fmt = function (n) { return n == null ? '' : Number(n).toLocaleString('en-US', { maximumFractionDigits: 0 }); };
        gs.forEach(function (x) {
          if (vistos[x.ticker] || cards.length >= 2) return;
          vistos[x.ticker] = 1;
          var pos = Number(x.total_gex) >= 0;
          // barras: strikes reais, largura proporcional ao MAIOR gamma absoluto
          var ts = (x.top_strikes || []).slice(0, 14);
          var maior = ts.reduce(function (m, s) { return Math.max(m, Math.abs(Number(s.gex) || 0)); }, 1);
          var bars = ts.map(function (s) {
            var call = (Number(s.gex) || 0) >= 0;
            var w = Math.max(6, Math.round(Math.abs(Number(s.gex) || 0) / maior * 100));
            return { strike: Number(s.strike).toLocaleString('en-US'),
              justify: call ? 'justify-content:flex-start' : 'justify-content:flex-end',
              barStyle: 'height:11px;border-radius:3px;width:' + w + '%;background:' + (call ? '#34d399' : '#f87171') + ';' };
          });
          cards.push({
            sym: x.ticker,
            desc: x.ticker === 'NQ' ? 'Nasdaq 100 Futures' : 'S&P 500 Futures',
            spot: fmt(x.spot_price),
            regime: pos ? 'Positive Gamma' : 'Negative Gamma',
            regimeStyle: 'padding:5px 12px;border-radius:8px;font-size:12px;font-weight:700;background:' +
              (pos ? 'rgba(52,211,153,0.14);color:#34d399;' : 'rgba(239,68,68,0.14);color:#f87171;'),
            total: (Number(x.total_gex) > 0 ? '+' : '') + fmt(x.total_gex) + 'M',
            totalColor: pos ? '#34d399' : '#f87171',
            levels: [
              { k:'Zero Gamma', v:fmt(x.zero_gamma), sub:'Gamma Flip',  color:'#fbbf24' },
              { k:'Put Wall',   v:fmt(x.put_wall),   sub:'Support',     color:'#34d399' },
              { k:'Call Wall',  v:fmt(x.call_wall),  sub:'Resistance',  color:'#f87171' },
              { k:'HVL',        v:fmt(x.hvl),        sub:'Price Magnet',color:'#22d3ee' },
              { k:'Vol Trigger',v:fmt(x.vol_trigger),sub:'Vol. Trigger',color:'#fb923c' },
              { k:'Max Pain',   v:fmt(x.max_pain),   sub:'Max Pain',    color:'#a78bfa' },
            ],
            bars: bars.length ? bars : undefined
          });
        });
        if (cards.length) { self._mcGexCards = cards; self._homeStatic = null; self.setState({ _mcGex: 1 }); }
      }).catch(function () {});
    self._homeStatic = null;
    self.setState({ _mcAna: 1 });
  }).catch(function () {});
}

// MINI HEATMAP DA HOME , mapa de ACOES de verdade (NVDA, AAPL, GOOGL, META...), que e o
// que a secao promete. Vinha com 9 quadradinhos de porcentagem INVENTADA ao lado da
// palavra "real time".
//
// A variacao NAO existe pronta em lugar nenhum: eu CALCULO a partir do `spot_price` de
// gex_levels, comparando o registro mais recente de cada papel com o anterior. E fechamento
// contra fechamento, dado do proprio Everton, sem depender de API de terceiro.
// ⚠️ Papel com um registro so fica DE FORA , sem dois pontos no tempo nao ha variacao, e
// inventar zero seria mentir que o papel nao andou.
_mcLigarMercado() {
  if (this._mcMercBuscou) return;
  this._mcMercBuscou = true;
  var self = this;
  var AN = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InFmd2hkdXZ1dGZ1bXNheG51b2ZhIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzQzNzc5NDYsImV4cCI6MjA4OTk1Mzk0Nn0.efRel6U68misvPSRj8-p31-gOhzjXN4eIFMiloTNyk4';
  fetch('https://qfwhduvutfumsaxnuofa.supabase.co/rest/v1/gex_levels' +
    '?select=date,ticker,spot_price&order=date.desc&limit=140',
    { headers: { apikey: AN, Authorization: 'Bearer ' + AN } })
    .then(function (r) { return r.ok ? r.json() : null; })
    .then(function (rows) {
      if (!rows || !rows.length) return;
      var por = {};
      rows.forEach(function (r) { (por[r.ticker] = por[r.ticker] || []).push(r); });
      var FORA = { ES: 1, NQ: 1, SPY: 1, QQQ: 1, GLD: 1 };   // indice e ETF nao sao "acao"
      var NOME = { NVDA:'NVDA', AAPL:'AAPL', GOOGL:'GOOGL', META:'META',
                   MSFT:'MSFT', AMZN:'AMZN', TSLA:'TSLA' };
      var lista = [];
      Object.keys(por).forEach(function (t) {
        if (FORA[t]) return;
        var v = por[t];
        if (v.length < 2 || !v[0].spot_price || !v[1].spot_price) return;
        var p = (Number(v[0].spot_price) / Number(v[1].spot_price) - 1) * 100;
        lista.push({ t: NOME[t] || t, p: p });
      });
      if (!lista.length) return;
      // maior movimento (pra cima ou pra baixo) no bloco grande, como num heatmap de verdade
      lista.sort(function (a, b) { return Math.abs(b.p) - Math.abs(a.p); });
      self._mcMini = lista.slice(0, 9).map(function (r, i) {
        var forte = Math.min(0.6, 0.14 + Math.abs(r.p) * 0.09);
        var fundo = r.p >= 0 ? 'rgba(191,255,0,' + forte + ')' : 'rgba(239,68,68,' + (forte + 0.06) + ')';
        var grande = i === 0;
        return {
          nome: r.t,
          pct: (r.p > 0 ? '+' : '') + r.p.toFixed(2) + '%',
          style: 'border-radius:8px;background:' + fundo + ';display:flex;flex-direction:column;' +
                 'align-items:center;justify-content:center;gap:2px;color:' +
                 (r.p >= 0 ? '#070a06' : '#fff') + ';font-size:' + (grande ? '13px' : '10.5px') + ';' +
                 (grande ? 'grid-row:span 2;' : '')
        };
      });
      self._homeStatic = null;
      self.setState({ _mcMerc: 1 });
    }).catch(function () {});
}

